(1623, 0, 'itIT', 'Vorrei controllare la mia cassetta di sicurezza.', ''),
(1624, 0, 'itIT', 'Voglio dare un''occhiata alla tua merce.', ''),
(1628, 0, 'itIT', 'Scotty, ho smarrito il mio segnalatore e me ne serve uno nuovo.', ''),
(1630, 0, 'itIT', 'Non sono un erbalista praticante... Posso comunque aiutarti nel tuo lavoro?', ''),
(1662, 0, 'itIT', 'Che ci fai qui fuori?', ''),
