(1802, 1, 'itIT', 'Vuoi comprare qualcosa?', ''),
(1822, 0, 'itIT', 'Non tutto è perduto, Kharan!', ''),
(1822, 1, 'itIT', 'Non sono qui per farti del male, Kharan. Mi manda Gor''shak. Mi ha detto che mi avresti parlato della Principessa.', ''),
(1823, 0, 'itIT', 'La porta è aperta, Kharan. Sei un uomo libero.', ''),
(1824, 0, 'itIT', 'Già.', ''),
(1825, 0, 'itIT', 'Va'' avanti con il tuo racconto.', ''),
(1827, 0, 'itIT', 'Cos''è successo?', ''),
(1828, 1, 'itIT', 'Continua...', ''),
(1831, 0, 'itIT', 'Non tutto è perduto, Kharan!', ''),
(1832, 0, 'itIT', 'Perché sei ancora in vita e le mie mani non sono avvinghiate intorno al tuo collo tozzo.', ''),
(1833, 0, 'itIT', 'Niente. Ho ricevuto l''ordine di parlare prima con te e poi con Thrall. So solo che Thrall è interessato a salvare la tua Principessa.', ''),
(1834, 0, 'itIT', 'Questo spiegherebbe come mai sei rinchiuso in una prigione in fondo a una montagna, dico bene, Nano?', ''),
(1835, 0, 'itIT', 'Cos''è successo?', ''),
(1837, 0, 'itIT', 'Va'' avanti con il tuo racconto.', ''),
(1838, 0, 'itIT', 'Già.', ''),
(1839, 0, 'itIT', 'Se può esserti d''aiuto, lascerò la porta della cella aperta. Come fare per uscire è un problema tuo. Addio, Kharan.', ''),
(1842, 0, 'itIT', 'Ecco la prova del mio successo, Cyrus.', ''),
