(5481, 0, 'itIT', 'Rokaro, ho perso l''Amuleto Fuocodrago. Puoi crearne un altro?', ''),
(5482, 0, 'itIT', 'Haleh, ho perso l''Amuleto Fuocodraco. Potresti realizzarne un altro?', ''),
(5483, 0, 'itIT', 'Barnil, credo di aver perso il Capitolo I.', ''),
(5483, 1, 'itIT', 'Barnil, credo di aver perso il Capitolo II.', ''),
(5483, 2, 'itIT', 'Barnil, credo di aver perso il Capitolo III.', ''),
(5483, 3, 'itIT', 'Barnil, credo di aver perso il Capitolo IV.', ''),
(5502, 0, 'itIT', 'Raene, ho perso la Verga della Trasformazione di Dartol.', ''),
(5630, 0, 'itIT', 'Larion, voglio aiutarti a combattere contro i parassiti!', ''),
(5665, 0, 'itIT', 'Addestrami.', ''),
(5667, 0, 'itIT', 'Ehi, Knot! Sono un Maestro Conciatore. Puoi insegnarmi a creare i Completi da Ogre?', ''),
(5667, 1, 'itIT', 'Ehi, Knot! Sono un sarto. Puoi insegnarmi a creare i Completi da Ogre?', ''),
(5675, 0, 'itIT', 'Cosa sai in proposito?', ''),
(5687, 0, 'itIT', 'Una battaglia?', ''),
(5688, 0, 'itIT', 'Ti prego di continuare.', ''),
(5689, 0, 'itIT', 'Ti ascolto, Demitrian.', ''),
(5701, 0, 'itIT', 'Colto di sorpresa? Come?', ''),
(5702, 0, 'itIT', '<Annuisci>', ''),
(5704, 0, 'itIT', 'Cosa fece poi Ragnaros?', ''),
(5708, 0, 'itIT', 'Sono il nuovo Re? Ma che dici?!?', ''),
(5708, 1, 'itIT', 'Scagnozzi? Tributo?', ''),
(5709, 0, 'itIT', 'Giocare? Sei pazzo?', ''),
(5710, 0, 'itIT', 'Brutto...', ''),
(5711, 0, 'itIT', 'Ascoltami bene, Imp: ti catturerò! E quando l''avrò fatto...', ''),
(5712, 0, 'itIT', 'MUORI!', ''),
(5713, 0, 'itIT', 'Preparati a incontrare il tuo creatore.', ''),
(5715, 0, 'itIT', 'È bello essere il Re! Ora torniamo a parlare dell''argomento precedente...', ''),
(5723, 0, 'itIT', 'Che storia triste. Grazie, spirito.', ''),
(5724, 0, 'itIT', 'Viviamo una tragedia senza fine.', ''),
(5725, 0, 'itIT', 'Dovrò uccidere qualcuno, vero?', ''),
(5726, 0, 'itIT', 'Interessante. Continua, ti prego.', ''),
(5727, 0, 'itIT', 'Ti prego di continuare.', ''),
(5728, 0, 'itIT', 'So molto poco degli Alti Nobili e nulla degli Shen''dralar.', ''),
(5729, 0, 'itIT', 'Spirito! Cos''è accaduto in questo posto?', ''),
(5733, 0, 'itIT', 'Sì, sei proprio un cervellone! Slip''kik, quanto credi di essere intelligente?', ''),
(5734, 0, 'itIT', 'Allora... Adesso sono io il Re! Cosa avete da darmi?', ''),
(5735, 0, 'itIT', 'Chiamami "Capo". Cosa mi hai portato?', ''),
(5738, 0, 'itIT', 'Ehm... è così che li ho trovati. Volevo dimostrare al Re che costituiscono una minaccia! A proposito, Capitano... ho sentito che la Guardia Fengus ti chiamava "inutile fidanzatino degli Gnoll"!', ''),
(5739, 0, 'itIT', 'Ehm... sto portando alcuni prigionieri al cospetto del Re perché siano puniti.', ''),
(5740, 0, 'itIT', 'E va bene... mostrami il tributo!', ''),
(5743, 0, 'itIT', 'Piangi la perdita.', ''),
(5743, 1, 'itIT', 'Piangi la perdita.', ''),
(5749, 0, 'itIT', '<Copi lo schema nel tuo quaderno d''Ingegneria.>', ''),
(5762, 0, 'itIT', 'Lexlort, ho perso le Manette di Torio.', ''),
(5764, 0, 'itIT', 'Perché dici che è una coincidenza, Rabine?', ''),
(5765, 0, 'itIT', 'Il Frutto della Fertilità?', ''),
(5766, 0, 'itIT', 'Ma qualcosa è andato storto, vero?', ''),
(5767, 0, 'itIT', 'Cosa accadrebbe se il Frutto della Fertilità, o la Vil Vite, venisse completamente corrotto?', ''),
(5812, 0, 'itIT', 'Sei tu il Forgiaterra capace di creare l''Elementio?', ''),
(5813, 0, 'itIT', 'Cosa sai in proposito, Franzahl?', ''),
(5814, 0, 'itIT', 'Una fenditura?', ''),
(5815, 0, 'itIT', 'Cosa successe?', ''),
(5818, 0, 'itIT', 'Gorzeeki, vorrei comprare qualcosa.', ''),
(5842, 0, 'itIT', 'E come faccio?', ''),
(5843, 0, 'itIT', 'Tutto ciò è molto interessante... ma di cosa hai bisogno?', ''),
(5844, 0, 'itIT', 'Quale compito?', ''),
(5845, 0, 'itIT', 'Sto cercando un grande e potente Stregone.', ''),
(5849, 2, 'itIT', 'Mostrami cos''hai da vendere.', ''),
(5851, 0, 'itIT', 'Capo degli Zoccolo Sanguinario, può sembrare una richiesta strana... ma ho un giovane allievo piuttosto timido. Per lui sei un eroe... e vorrebbe avere l''impronta del tuo zoccolo.', ''),
(5853, 0, 'itIT', 'Addestrami.', ''),
(5854, 0, 'itIT', 'Addestrami.', ''),
(5855, 0, 'itIT', 'Addestrami.', ''),
(5856, 0, 'itIT', 'Addestrami.', ''),
(5864, 0, 'itIT', 'Vorrei acquistare qualcosa.', ''),
(5868, 0, 'itIT', 'Tentatrice, il tuo travestimento non m''inganna. È giunta la tua ora.', ''),
(5870, 0, 'itIT', 'Dunque tu saresti Klinfran il Pazzo? Che delusione... mi aspettavo una sfida più impegnativa. Osi affrontarmi nella tua vera forma?', ''),
(5871, 0, 'itIT', 'Io ti conosco col nome di Artorius l''Araldo della Rovina. Mostrati, demone! Affrontami!', ''),
(5872, 0, 'itIT', 'Uno Gnomo? Patetico. Affrontarmi, demone!', ''),
(5962, 0, 'itIT', 'Vorrei vedere la tua merce.', ''),
(5967, 0, 'itIT', 'Mi serve una cavalcatura.', ''),
(6023, 0, 'itIT', 'Mi serve una cavalcatura.', ''),
(6059, 1, 'itIT', 'Fammi vedere la tua merce.', ''),
(6086, 0, 'itIT', 'Vorrei acquistare qualcosa.', ''),
(6087, 0, 'itIT', 'Vorrei acquistare qualcosa.', ''),
(6087, 1, 'itIT', 'Cosa puoi insegnarmi?', ''),
(6092, 0, 'itIT', 'Questo Implosore Dimensionale sembra roba pericolosa! Come posso realizzarne uno?', ''),
(6094, 0, 'itIT', 'Devo costruire un segnalatore per questo magnifico dispositivo!', ''),
(6141, 0, 'itIT', 'Quali merci da usare nella Forra dei Cantaguerra posso acquistare?', ''),
(6142, 0, 'itIT', 'Quali merci da usare nella Forra dei Cantaguerra posso acquistare?', ''),
(6162, 0, 'itIT', 'Mi serve una cavalcatura.', ''),
(6185, 0, 'itIT', 'Lo uccido sul posto, così come il mio sovrano si aspetta che io faccia. Non è altro che un ladro e un bugiardo.', ''),
(6185, 1, 'itIT', 'Lo porto al cospetto del mio sovrano perché lo punisca. Ha infranto la legge di questa terra, quindi è mio dovere arrestarlo.', ''),
(6185, 2, 'itIT', 'Sequestro il grano che ha rubato, lo avviso che la via del furto porta alla disfatta e alla distruzione, ma gli permetto di tornare dalla sua famiglia.', ''),
(6185, 3, 'itIT', 'Gli permetto di prendere grano a sufficienza per nutrire la sua famiglia per un paio di giorni, incoraggiandolo a lasciare questa terra.', ''),
(6186, 0, 'itIT', 'Sono pronto a scoprire quale sarà il mio futuro!', ''),
(6187, 0, 'itIT', 'Lo giustizio, così come da istruzioni del mio sovrano. Come punizione per i suoi crimini contro il mio popolo, deve soffrire orribilmente prima di morire.', ''),
(6187, 1, 'itIT', 'Lo giustizio, così come da istruzioni del mio sovrano. Però lo faccio soffrire il meno possibile. Bisogna fare giustizia, ma un po'' di compassione non guasta.', ''),
(6187, 2, 'itIT', 'Rischio la mia vita e lo libero, così che possa dimostrare la propria innocenza. Se potrò, lo aiuterò in ogni modo.', ''),
(6202, 0, 'itIT', 'Fammi vedere la tua merce.', ''),
(6202, 1, 'itIT', 'Dimmi di più su queste Carte di Lunacupa.', ''),
(6207, 8, 'itIT', 'Esistono altri mazzi?', ''),
(6208, 0, 'itIT', 'Contesto il comportamento malvagio del governante, difendendo l''onore del mio sovrano a costo di mettere a rischio i futuri rapporti diplomatici.', ''),
(6208, 1, 'itIT', 'Ignoro l''insulto lamentandomi. Spero di instillare nel governante il timore di aver sbagliato. Al ritorno dal mio sovrano, lo informo dell''accaduto.', ''),
(6208, 2, 'itIT', 'Ignoro l''insulto in silenzio. Non lo riferirò al mio sovrano, poiché devo assicurare la pace a ogni costo. In fondo, è solo un insulto e non una dichiarazione di guerra.', ''),
(6209, 0, 'itIT', 'Mi esprimo negativamente sull''ingresso di mio fratello nell''ordine, incrinando per sempre il nostro rapporto. È un pericolo per se stesso e per coloro che lo circondano: sperare che migliori col tempo significa correre un rischio troppo grande.', ''),
(6209, 1, 'itIT', 'Mi esprimo favorevolmente sull''ingresso di mio fratello nell''ordine, probabilmente minandone la sicurezza. Posso aiutarlo con le regole e confido nella sua abilità di apprendere e adattarsi.', ''),
(6209, 2, 'itIT', 'Utilizzo dei sotterfugi per impedire a mio fratello di entrare nell''ordine. Posso farlo senza che se ne accorga: in questo modo, i nostri rapporti non verranno incrinati.', ''),
(6210, 0, 'itIT', 'Mostro al mio sovrano l''orecchio della bestia, affermando di averla uccisa personalmente e prendendo la ricompensa. Prendersi i meriti di un''impresa compiuta da qualcun altro è sbagliato.', ''),
(6210, 1, 'itIT', 'Mostro al mio sovrano l''orecchio della bestia, affermando di averla uccisa personalmente: in fondo, è andata proprio così. Poi offro una parte della ricompensa al cavaliere senza lavoro per aiutare la sua famiglia.', ''),
(6210, 2, 'itIT', 'Rimango in silenzio sull''uccisione, permettendo al cavaliere di ottenere la ricompensa per aiutare la sua famiglia.', ''),
(6211, 0, 'itIT', 'Mi piacerebbe avere uno di quei Biglietti della Fortuna di cui mi hai parlato! Ho giusto lo spazio necessario nel mio inventario.', ''),
(6213, 1, 'itIT', 'La Fiera di Lunacupa è già qui? Dove si trova?', ''),
(6214, 0, 'itIT', 'Quando arriverà la Fiera di Lunacupa, dove sarà?', ''),
(6230, 0, 'itIT', 'Fammi vedere le bevande!', ''),
(6231, 0, 'itIT', 'Mi stai dicendo che vendi rane?', ''),
(6233, 0, 'itIT', 'Cos''è che vendi?', ''),
(6234, 0, 'itIT', 'Mmm... cibo.', ''),
(6342, 0, 'itIT', 'Fammi dare un''occhiata ai tuoi fuochi d''artificio.', ''),
(6343, 0, 'itIT', 'Fammi dare un''occhiata ai tuoi fuochi d''artificio.', ''),
(6443, 0, 'itIT', 'Impara la ricetta.', ''),
(6445, 0, 'itIT', 'Voglio pescare Gahz''ranka! Dimmi come posso fare!', ''),
(6461, 0, 'itIT', 'Vorrei scendere nel campo di battaglia.', ''),
(6465, 0, 'itIT', 'Vorrei scendere nel campo di battaglia.', ''),
(6470, 0, 'itIT', 'Vorrei scendere nel campo di battaglia.', ''),
(6470, 1, 'itIT', 'Mostrami cos''hai da vendere.', ''),
(6471, 0, 'itIT', 'Vorrei scendere nel campo di battaglia.', ''),
(6475, 0, 'itIT', 'Vorrei scendere nel campo di battaglia.', ''),
(6478, 0, 'itIT', 'Voglio unirmi alla battaglia!', ''),
(6492, 0, 'itIT', 'Voglio unirmi alla battaglia!', ''),
(6498, 0, 'itIT', 'Voglio unirmi alla battaglia!', ''),
(6500, 0, 'itIT', 'Voglio unirmi alla battaglia!', ''),
(6510, 0, 'itIT', 'Voglio unirmi alla battaglia!', ''),
(6520, 0, 'itIT', 'Sì, per favore.', ''),
(6521, 0, 'itIT', 'Quali merci posso acquistare dai Profanatori?', ''),
(6522, 0, 'itIT', 'Quali merci posso acquistare dalla Lega di Arathor?', ''),
(6525, 0, 'itIT', 'Dolcetto o scherzetto!', ''),
(6525, 2, 'itIT', 'Vorrei vedere le tue merci, Calandrath.', ''),
(6526, 0, 'itIT', 'Fammi vedere la tua merce.', ''),
(6528, 0, 'itIT', 'Fammi vedere la tua merce.', ''),
(6529, 0, 'itIT', 'Baristolth, ho perso il mio distintivo e me ne serve un altro.', ''),
(6533, 0, 'itIT', 'Salve, Frankal. Ho sentito che potresti avere delle informazioni su dove si trova la Signora Natalia Mar''alith.', ''),
(6534, 0, 'itIT', 'Salve, Frankal. Ho sentito che potresti avere delle informazioni su dove si trova la Signora Natalia Mar''alith.', ''),
(6535, 0, 'itIT', 'Cospargimi la faccia di cenere come se fosse una pittura di guerra!', ''),
(6540, 0, 'itIT', 'Non sono un cultista, mostro! Affronta la tua distruzione!', ''),
(6540, 1, 'itIT', 'Templare Cremisi! Possiedo la tua Insegna del Richiamo. Ascolta la mia evocazione!', ''),
(6540, 2, 'itIT', 'Templare di Zaffiro! Possiedo la tua Insegna del Richiamo. Ascolta la mia evocazione!', ''),
(6540, 3, 'itIT', 'Templare Terrigeno! Possiedo la tua Insegna del Richiamo. Ascolta la mia evocazione!', ''),
(6540, 4, 'itIT', 'Templare Hoary! Possiedo la tua Insegna del Richiamo. Ascolta la mia evocazione!', ''),
(6542, 0, 'itIT', 'Tu mi ascolterai, vile Duca! Non sono uno dei tuoi tirapiedi del Martello del Crepuscolo! Sono qui per sfidarti! Vieni! Vieni e affronta la morte...', ''),
(6542, 1, 'itIT', 'Duca delle Braci! Ho il tuo anello con sigillo! Ascolta la mia evocazione!', ''),
(6542, 2, 'itIT', 'Duca degli Abissi! Ho il tuo anello con sigillo! Ascolta la mia evocazione!', ''),
(6542, 3, 'itIT', 'Duca dei Cristalli! Ho il tuo anello con sigillo! Ascolta la mia evocazione!', ''),
(6542, 4, 'itIT', 'Duca degli Zefiri! Ho il tuo anello con sigillo! Ascolta la mia evocazione!', ''),
(6543, 1, 'itIT', 'Skaldrenox! Ho il tuo scettro e ti ordino di entrare in questo mondo!', ''),
(6543, 2, 'itIT', 'Skwol! Ho il tuo scettro! Ti ordino di entrare in questo mondo!', ''),
(6543, 3, 'itIT', 'Kazum! Ho il tuo scettro! Ti ordino di entrare in questo mondo!', ''),
(6543, 4, 'itIT', 'Turbinaxis! Ho il tuo scettro! Ti ordino di entrare in questo mondo!', ''),
(6545, 0, 'itIT', 'Tornerò quando avrò districato questa matassa.', ''),
(6546, 0, 'itIT', 'Posseduta da cosa?', ''),
(6547, 0, 'itIT', 'Perse il controllo? Cosa vuoi dire?', ''),
(6548, 0, 'itIT', 'Quali richieste?', ''),
(6549, 0, 'itIT', 'Natalia?', ''),
(6550, 0, 'itIT', 'Cosa le è successo dopo?', ''),
(6551, 0, 'itIT', 'Sembra pericoloso.', ''),
(6552, 0, 'itIT', 'Grazie delle informazioni, Frankal.', ''),
(6553, 0, 'itIT', 'Che storia! Così, è entrata nell''Alveare Regal e nessuno l''ha più vista?', ''),
