(7401, 0, 'itIT', 'Noi abbiamo molto in comune, Elfo della Notte. Non posso fare a meno di pensare che sia stato il destino a farci incontrare. Lasciati aiutare da me e dal mio popolo, Cowlen. Ci riscatteremo per i torti che abbiamo commesso, te lo giuro.', ''),
(7402, 0, 'itIT', 'Temo che la mia gente sia in qualche modo responsabile per quanto è accaduto. Noi siamo profughi, cacciati dalle nostre case dalla Legione Infuocata. Questa tragedia è il risultato della nostra ultima fuga. La nostra astronave si è schiantata e questi detriti sono una parte di ciò che ne resta.', ''),
(7403, 0, 'itIT', 'Non sono qui per ucciderti, Elfo della Notte. E non sono stati gli dei a farti questo...', ''),
(7415, 0, 'itIT', 'Sono pronto per volare a Exodar.', ''),
(7421, 0, 'itIT', 'Non sono un attore.', ''),
(7422, 0, 'itIT', 'Va bene, ci proverò.', ''),
(7426, 0, 'itIT', 'È finita, Scintilla. L''Ammiraglio sa che sei stato tu a tradire l''Alleanza. Scegli: o collabori con me e mi dici tutto quello che sai o dovremo batterci.', ''),
