(7481, 0, 'itIT', 'Dolcetto o scherzetto!', ''),
(7481, 2, 'itIT', 'Voglio dare un''occhiata alla tua merce.', ''),
(7482, 0, 'itIT', 'Ascoltami, $GUmano:Umana;. Le tue suppliche non mi interessano, ma tu hai qualcosa che voglio. Dimmi dove trovare i Lingotti Forgiati nel Sangue.', ''),
(7484, 0, 'itIT', 'Come si fa a creare una gilda?', ''),
(7484, 1, 'itIT', 'Voglio creare un''insegna di gilda.', ''),
(7494, 0, 'itIT', 'Cerco qualcuno che mi addestri nella Forgiatura.', ''),
(7495, 0, 'itIT', 'Guardiana Leesa''oh, cosa ci fai qua fuori?', ''),
(7499, 0, 'itIT', 'Thrall, stiamo per liberarti. Andiamo!', ''),
(7499, 1, 'itIT', 'Thrall, stiamo per liberarti. Andiamo!', ''),
(7502, 0, 'itIT', 'Sì per favore, continua.', ''),
(7503, 0, 'itIT', 'Sì, se non ti dispiace.', ''),
(7504, 0, 'itIT', 'Nobundo, continua per favore.', ''),
(7505, 0, 'itIT', 'Cosa ti disse?', ''),
(7506, 0, 'itIT', 'Cos''è stato?', ''),
(7507, 0, 'itIT', 'Cos''hai fatto?', ''),
(7508, 0, 'itIT', 'Continua, per favore.', ''),
(7512, 0, 'itIT', 'Addestrami.', ''),
(7517, 0, 'itIT', 'Insegnami, ti prego.', ''),
(7520, 0, 'itIT', 'Va bene, Morsic. Ti libero.', ''),
(7520, 1, 'itIT', 'Naturalista, dammi il tuo dono.', ''),
(7522, 0, 'itIT', 'Insegnami l''arte di comunicare con gli spiriti.', ''),
(7522, 1, 'itIT', 'Vorrei riassegnare i miei talenti.', ''),
(7524, 0, 'itIT', 'Voglio dare un''occhiata alla tua merce.', ''),
(7524, 1, 'itIT', 'Addestrami.', ''),
(7531, 0, 'itIT', 'Sono prigioniero come te, non lo vedi? Quegli sporchi Draenei mi hanno catturato non appena sono uscito dalla Porta del Sole. Hanno distrutto i nostri Controlli del Portale e la Porta stessa. Il Re del Sole sarà molto contrariato per come sono andate le cose.', ''),
(7533, 0, 'itIT', 'L''ho detto e tu mi hai creduto. Grazie delle informazioni. Ci hai aiutato più di quanto tu possa immaginare.', ''),
(7534, 0, 'itIT', 'La Bobina di Alimentazione è enorme. Spero che ci sia più di un Abominio a difesa dei suoi numerosi punti deboli.', ''),
(7535, 0, 'itIT', 'Sironas è un Eredar? Voglio dire... ma certo, ovviamente.', ''),
(7536, 0, 'itIT', 'Incredibile. Come ha fatto Sironas a fare una cosa del genere?', ''),
(7537, 0, 'itIT', 'Ah sì, Sironas. Me ne ero quasi dimenticato. Ho servito Sironas nelle Terre Esterne, però non avevo mai sentito parlare di questo Abominio. Quei dannati Draenei mi hanno catturato prima che potessi materializzarmi completamente in questo mondo.', ''),
(7540, 0, 'itIT', 'Naturalista, dammi il tuo dono.', ''),
(7552, 32918, 'itIT', 'Dama Marefiero, io e miei compagni siamo dalla tua parte.', ''),
(7552, 32919, 'itIT', 'Dama Marefiero, siamo pronti ad affrontare qualsiasi cosa Archimonde ci scagli contro.', ''),
(7552, 32920, 'itIT', 'Alla prossima, Dama Marefiero.', ''),
(7557, 0, 'itIT', 'Parlami dei Difensori.', ''),
(7559, 0, 'itIT', 'Donami il tuo marchio, antico saggio.', ''),
(7560, 0, 'itIT', 'Donami il tuo marchio, potente antico.', ''),
(7566, 0, 'itIT', 'Voglio approfondire la mia conoscenze delle arti degli Stregoni.', ''),
(7566, 1, 'itIT', 'Vorrei riassegnare i miei talenti.', ''),
(7567, 0, 'itIT', 'Cerco qualcuno che mi addestri come Druido.', ''),
(7567, 1, 'itIT', 'Vorrei riassegnare i miei talenti.', ''),
(7571, 0, 'itIT', 'Vorrei scordare la maestria nelle Pozioni.', ''),
(7571, 1, 'itIT', 'Ho completato nuovamente l''addestramento come alchimista. Desidero specializzarmi in pozioni.', ''),
(7579, 0, 'itIT', 'Hemet Nesingwary, cosa ci fai qui nelle Terre Esterne?', ''),
(7581, 35377, 'itIT', 'Non abbiamo nulla da temere.', ''),
(7581, 35378, 'itIT', 'Thrall, sono con te.', ''),
(7581, 35379, 'itIT', 'Alla prossima, Thrall.', ''),
(7582, 0, 'itIT', 'Salute, anziano. È arrivato il momento per la tua gente di cessare ogni ostilità contro i Draenei e i loro alleati.', ''),
(7583, 0, 'itIT', 'Non era mia intenzione ingannarti, anziano. I Draenei di Telredor pensavano di rivolgersi a te in una maniera che ti risultasse più familiare.', ''),
(7585, 0, 'itIT', 'Glielo dirò. Addio, anziano.', ''),
