(7675, 0, 'itIT', 'Ho ucciso molti dei tuoi Ogre, Lantresor. Non ho paura.', ''),
(7676, 0, 'itIT', 'Cosa devo fare?', ''),
(7677, 0, 'itIT', 'Allora combatteremo fino alla fine, Lantresor. Non staremo a guardare, mentre saccheggi le nostre città e uccidi la nostra gente.', ''),
(7678, 0, 'itIT', 'La mia gente chiede che fermi i tuoi Ogre Rocciadura e sospendi gli attacchi contro il nostro territorio. In cambio anche noi ritireremo le nostre truppe.', ''),
(7679, 0, 'itIT', 'Chiedo scusa. Non volevo offendere. Sono qui a nome della mia gente.', ''),
(7680, 0, 'itIT', 'Ho sentito parlare della tua razza, ma non avrei mai pensato di incontrare un mezzosangue.', ''),
(7681, 0, 'itIT', 'E l''altra metà?', ''),
(7682, 0, 'itIT', 'Dovrei saperlo? A me sembri un Orco.', ''),
(7690, 0, 'itIT', 'Addestrami.', ''),
(7691, 0, 'itIT', 'Addestrami.', ''),
(7692, 0, 'itIT', 'Ramos, so che da qualche parte dentro di te si nasconde la verità. Dimmi di cosa si tratta.', ''),
(7704, 0, 'itIT', 'Empoor, mi dirai quello che voglio sapere o te ne pentirai!', ''),
(7704, 1, 'itIT', 'Dimmi ancora ciò che sai!', ''),
(7706, 34158, 'itIT', 'Sacerdotessa, ti sarò grato per qualsiasi aiuto potrai fornirmi.', ''),
