(7724, 1, 'itIT', 'Ho contrassegni da scambiare!', ''),
(7725, 0, 'itIT', 'Mi manda Altruis. Dice che potresti essere in grado di aiutarmi.', ''),
(7726, 0, 'itIT', 'Non mollare! Cosa mi dici delle Paludi di Zangar?', ''),
(7727, 0, 'itIT', 'Non ho tempo da perdere! Custode, cos''è successo?!?', ''),
(7729, 0, 'itIT', 'Mi manda Sal''salabim per riscuotere un tuo debito. Paga o dovrò farti male.', ''),
(7730, 0, 'itIT', 'Mi manda Sal''salabim per riscuotere un tuo debito. Paga o dovrò farti male.', ''),
