(7762, 0, 'itIT', 'Posso fare qualcosa per te, Madre Anziana?', ''),
(7763, 0, 'itIT', 'Qual è questo dovere?', ''),
(7764, 0, 'itIT', 'Andare via? Come puoi scegliere di andartene?', ''),
(7765, 0, 'itIT', 'Cosa si può fare? Ho provato molte cose diverse. Ho fatto del mio meglio per aiutare la gente di Nagrand. Ogni volta che ho avvicinato Garrosh, mi ha allontanato.', ''),
(7766, 0, 'itIT', 'Ci credi?', ''),
