(7974, 0, 'itIT', 'Ho fatto tutto ciò che ho potuto, Madre Anziana. Grazie per le tue parole gentili.', ''),
(7976, 0, 'itIT', 'Tornerò subito su Azeroth, Madre Anziana.', ''),
(7977, 0, 'itIT', 'È il mio Capoguerra, Madre Anziana. La guida della mia gente. Viene dal mio mondo. È... il figlio di Durotan. È tuo nipote.', ''),
(7978, 0, 'itIT', 'Madre Anziana, non ho mai avuto l''onore. Durotan è morto molto prima che io nascessi, ma le sue gesta eroiche sono note a tutti nel mio mondo. Gli Orchi di Azeroth vivono in un luogo chiamato Durotar, chiamato così per onorare tuo figlio. E... <Ti fermi un attimo per prendere fiato e pensare alle giuste parole da dire alla Madre Anziana.>', ''),
(7979, 0, 'itIT', 'Madre Anziana, sei tu la madre di Durotan?', ''),
(7981, 0, 'itIT', 'Ho perso il Bastone dell''Arcimago Vargoth. Sai come rimpiazzarlo?', ''),
(7982, 1, 'itIT', 'Voglio dare un''occhiata alla tua merce.', ''),
(7984, 0, 'itIT', 'Continua a leggere, se ne hai il coraggio...', ''),
(7985, 0, 'itIT', 'Continua a leggere, se ne hai il coraggio...', ''),
(7986, 0, 'itIT', 'Continua a leggere, se ne hai il coraggio...', ''),
(7987, 0, 'itIT', 'Continua a leggere, se ne hai il coraggio...', ''),
(7988, 0, 'itIT', 'Continua a leggere, se ne hai il coraggio...', ''),
(7989, 0, 'itIT', 'Continua a leggere, se ne hai il coraggio...', ''),
(7999, 0, 'itIT', 'Grek, proveresti questo nuovo Olio per Armi che ha preparato Rakoria?', ''),
(8001, 0, 'itIT', 'Scarpone, vediamo se hai qualcosa da mandare giù.', ''),
(8009, 0, 'itIT', 'Continua, te ne prego.', ''),
(8010, 0, 'itIT', 'Capisco.', ''),
(8011, 0, 'itIT', 'Cos''hai fatto?', ''),
