(8013, 0, 'itIT', 'Capisco.', ''),
(8014, 0, 'itIT', 'Volevo chiederti un''altra cosa.', ''),
(8021, 0, 'itIT', 'Mostrami cos''hai da vendere, "Secco".', ''),
(8023, 0, 'itIT', '<Premi un pulsante a caso.>', ''),
(8033, 0, 'itIT', 'Ezekiel ha detto che possiedi un certo libro...', ''),
(8036, 0, 'itIT', '<Attivare il blocco d''emergenza.>', ''),
