(8060, 1, 'itIT', 'NO!', ''),
(8062, 0, 'itIT', 'Tenti di contattare il Commerciante del Vento Marid.', ''),
(8063, 0, 'itIT', 'Fornitore Hazzin, vediamo cosa hai da offrirmi?', ''),
(8070, 0, 'itIT', 'Cos''hai in vendita, Tuluman?', ''),
(8071, 0, 'itIT', 'Commerciante del Vento Marid, ho delle nuove informazioni sui Drachi Fatui. Voglio diventare suo socio in affari e per una somma extra, mi prenderò cura degli Elfi e dei loro amici Umani.', ''),
(8072, 0, 'itIT', 'Portami nella tana del padrone.', ''),
(8079, 0, 'itIT', 'Vorrei scendere nel campo di battaglia.', ''),
