(9212, 0, 'itIT', 'Durkot, sono pronto a partire.', ''),
(9212, 1, 'itIT', 'Vorrei mettere il mio famiglio qui.', ''),
(9217, 0, 'itIT', 'Cosa sai sul Culto dei Dannati?', ''),
(9218, 0, 'itIT', 'Ho motivo di credere che tu sia coinvolto nell''attività dei cultisti.', ''),
(9218, 1, 'itIT', 'Fammi vedere la tua merce.', ''),
(9219, 0, 'itIT', 'Da quanto tempo lavori per il Culto dei Dannati?', ''),
(9245, 2, 'itIT', 'Fammi vedere la tua merce.', ''),
(9253, 0, 'itIT', 'Qual è la causa di questo conflitto?', ''),
(9253, 1, 'itIT', 'Ho perso la Prigione Arcana Aumentata. L''ho lasciata a te?', ''),
(9262, 0, 'itIT', 'Sono pronto ad affrontare Saragosa!', ''),
(9262, 1, 'itIT', 'Keristrasza, io qui ho finito. Ti prego di riportarmi alla Cupola di Transito.', ''),
(9280, 0, 'itIT', 'Esamina il cadavere in cerca del Totem di Issliruk.', ''),
(9283, 0, 'itIT', 'Chi è Malygos?', ''),
(9285, 0, 'itIT', 'Mi fate un rapporto sulla situazione, Capitano?', ''),
(9286, 2, 'itIT', 'Qual è lo stato attuale delle Porte del Pozzo Solare?', ''),
(9286, 3, 'itIT', 'Ora che Kalecgos è libero, puoi teletrasportarmi all''Apogeo?', ''),
(9286, 5, 'itIT', 'Abbiamo sgombrato la strada per arrivare a Kil''jaeden! Puoi teletrasportarmi nei pressi del Pozzo Solare?', ''),
(9287, 0, 'itIT', 'Cos''è andato male?', ''),
(9288, 0, 'itIT', 'Perché si sono fermati?', ''),
(9289, 0, 'itIT', 'Ogni suggerimento sarà molto apprezzato.', ''),
(9297, 0, 'itIT', 'Non sei solo qui?', ''),
(9297, 1, 'itIT', 'Cosa vuole Kil''jaeden da una donna mortale?', ''),
(9299, 3, 'itIT', 'Vorrei acquistare qualcosa.', ''),
(9301, 0, 'itIT', 'Forza, Budd. È ora di giocare con i Troll dei Ghiacci!', ''),
(9302, 0, 'itIT', 'Non temere, Taunka: l''Orda salverà e proteggerà te e il tuo popolo. Prima, però devi giurare fedeltà al Capoguerra, pronunciando il Giuramento di Sangue dell''Orda.', ''),
(9303, 0, 'itIT', 'Per l''Orda!

Equipaggiati con il contenuto delle casse che ci circondano e raggiungi il Martello di Agmar a est. La tua prima prova come membro dell''Orda è sopravvivere al viaggio.

Lok''tar ogar!', ''),
(9304, 0, 'itIT', 'Allora ripeti dopo di me: "Lok''tar ogar! Vittoria o morte! Sono queste le parole che mi legano all''Orda, poiché sono le verità fondamentali e sacre di qualsiasi guerriero che ne faccia parte.

Sono pronto a donare la mia carne e il mio sangue al Capoguerra perché ne faccia ciò che desidera. Sono l''arma al suo comando.

Da questo momento, e fino alla fine dei miei giorni, io vivrò e morirò... per l''Orda!".', ''),
(9305, 0, 'itIT', 'Sì, Taunka. Tutti i membri dell''Orda hanno diritto alla vendetta.', ''),
(9307, 0, 'itIT', 'Ho qualcos''altro da chiederti.', ''),
(9335, 0, 'itIT', 'Mmm... la rana dice che sei un traditore, "amico".', ''),
(9352, 0, 'itIT', 'Spegni il falò dell''Alleanza con i piedi!', ''),
