(9415, 0, 'itIT', 'Sono pronto. Preparami per il teletrasporto!', ''),
(9416, 0, 'itIT', 'Mack, mi serve un po'' del tuo ottimo grog.', ''),
(9417, 0, 'itIT', 'Ora o mai più, Thassarian.', ''),
(9418, 0, 'itIT', 'Ora o mai più, Thassarian.', ''),
(9422, 0, 'itIT', 'Ho perso il Dispositivo di Controllo del Segatronchi... Per caso ne hai un altro?', ''),
(9426, 0, 'itIT', 'Rimuovi l''Occhio dei Profeti dal volto dell''idolo.', ''),
(9427, 3, 'itIT', 'Fammi vedere la tua merce.', ''),
(9429, 0, 'itIT', 'Ti faccio vedere io! Dammi il paracadute da esercitazione!', ''),
(9429, 1, 'itIT', 'Ti faccio vedere io! Dammi il paracadute da esercitazione!', ''),
(9437, 0, 'itIT', 'Vorrei usare le stalle.', ''),
(9453, 0, 'itIT', 'Fammi vedere la tua merce.', ''),
(9455, 0, 'itIT', 'Custode, permettimi di cavalcare uno dei drachi fino alla sala della Regina in cima al tempio.', ''),
(9457, 0, 'itIT', 'Sì, grazie. Vorrei tornare al livello inferiore del tempio.', ''),
(9459, 0, 'itIT', 'Addestrami.', ''),
(9461, 0, 'itIT', 'Salve, Gran Capo. Mi faresti l''onore di accettare l''invito a unirti all''Orda, come membro ufficiale e capo dei Taunka?', ''),
(9462, 0, 'itIT', 'L''onore è mio, Gran Capo. Ti prego di leggere questa pergamena: è il giuramento di fedeltà.', ''),
(9470, 0, 'itIT', 'Chi è il Cavaliere Senza Testa?', ''),
(9472, 0, 'itIT', 'Vorrei un passaggio per la Cupola di Transito.', ''),
(9472, 1, 'itIT', 'Posso usare un draco per volare da un''altra parte?', ''),
(9474, 0, 'itIT', 'Fammi vedere la tua merce.', ''),
(9476, 2, 'itIT', 'Voglio dare un''occhiata alla tua merce.', ''),
(9477, 4, 'itIT', 'Fammi vedere la tua merce.', ''),
(9478, 3, 'itIT', 'Fammi vedere la tua merce.', ''),
