(9484, 1, 'itIT', 'Vediamo cos''hai da vendere, Mastro Bracconiere.', ''),
(9485, 0, 'itIT', 'Cosa puoi dirmi di Loken e dei Nani del Ferro?', ''),
(9487, 0, 'itIT', 'Fammi vedere la tua merce.', ''),
(9488, 0, 'itIT', 'Hai degli oggetti che possa provare?', ''),
(9492, 0, 'itIT', 'Usa la latrina.', ''),
(9492, 1, 'itIT', 'Usa la latrina.', ''),
(9495, 0, 'itIT', 'Fammi vedere la tua merce.', ''),
(9496, 0, 'itIT', 'Abbiamo le ceneri purificate dell''Arboscello di Vordrassil. Se solo riuscissimo a soggiogare Ursoc, potremmo risanare la sua anima.', ''),
(9497, 0, 'itIT', 'Tur, assumi la tua Forma d''Orso.', ''),
(9497, 1, 'itIT', 'Aiutaci a soggiogarlo.', ''),
(9497, 2, 'itIT', 'Un guaritore ci farebbe comodo.', ''),
(9498, 2, 'itIT', 'Illusia, vorrei vedere la tua merce.', ''),
(9500, 0, 'itIT', 'Orsonn, sei libero di andare, ma prima dimmi cosa affligge i Mezzorsi.', ''),
(9501, 0, 'itIT', 'Agente Skully, devi usare di nuovo lo Specchio Magico della Banshee su di me!', ''),
(9502, 0, 'itIT', 'E poi cos''accadde?', ''),
(9503, 0, 'itIT', 'Grazie, figlio di Ursoc. Vedrò cosa posso fare.', ''),
(9504, 0, 'itIT', 'E chi era quello straniero?', ''),
(9505, 0, 'itIT', 'Grazie, Kodian. Farò ciò che posso.', ''),
(9507, 1, 'itIT', 'Sai dove hanno imprigionato il Cancelliere Amai?', ''),
(9507, 3, 'itIT', 'Hai visto dove hanno portato l''Ingegnere Burke?', ''),
(9508, 0, 'itIT', 'Non oggi, Esperto Scrivano!', ''),
(9508, 1, 'itIT', 'Sai dove hanno imprigionato il Cancelliere Amai?', ''),
(9508, 2, 'itIT', 'Hai visto dove hanno portato l''Ingegnere Burke?', ''),
(9508, 3, 'itIT', 'Sai dove tengono prigioniera la Guardiamorte Schneider?', ''),
(9509, 1, 'itIT', 'Sai dove hanno imprigionato il Cancelliere Amai?', ''),
(9509, 3, 'itIT', 'Sai dove tengono prigioniera la Guardiamorte Schneider?', ''),
(9510, 0, 'itIT', 'No, Cancelliere... non direi proprio che sono qui per salvarti.', ''),
(9510, 2, 'itIT', 'Hai visto dove hanno portato l''Ingegnere Burke?', ''),
(9510, 3, 'itIT', 'Sai dove tengono prigioniera la Guardiamorte Schneider?', ''),
(9511, 0, 'itIT', 'Sono pronto per essere teletrasportato a Dalaran.', ''),
(9512, 0, 'itIT', 'Libera e controlla il Portatore delle Fiamme.', ''),
(9513, 0, 'itIT', 'Sono pronto per essere teletrasportato a Dalaran.', ''),
(9517, 0, 'itIT', 'Vorrei inserire il codice segreto per ricevere il mio Souvenir del Concorrente.', ''),
(9528, 0, 'itIT', 'Sì, sono pronto a partire per la Baia della S.P.R. & Co.', ''),
(9532, 0, 'itIT', 'Vostra Eminenza, potremmo scambiare due parole in privato?', ''),
(9536, 0, 'itIT', 'Sono pronto, Vostra Grazia. <Bacia l''anello.>', ''),
(9537, 0, 'itIT', 'Uno dei Cultisti è inciampato sulla mia spada ed è morto. Posso avere un nuovo travestimento? Prometto che stavolta starò più attento.', ''),
(9541, 0, 'itIT', 'Scusa per il disturbo. Continua pure!', ''),
(9542, 0, 'itIT', 'Orik, mi serve un altro Elisir di Erbanotte.', ''),
(9543, 0, 'itIT', 'Tieni alta la testa! Sono sicuro che Arthas tornerà da un momento all''altro.', ''),
(9544, 0, 'itIT', 'Ora devo andare. Tieni gli occhi aperti!', ''),
(9545, 0, 'itIT', 'Sono sicuro che andrà tutto bene.', ''),
(9548, 0, 'itIT', 'Cos''hai per me?', ''),
(9549, 0, 'itIT', 'Mi piacerebbe acquistare la birra di questo mese.', ''),
(9550, 0, 'itIT', 'E perché mai dovrei voler usare un Segatronchi?', ''),
