(9561, 0, 'itIT', 'Ho un''altra domanda.', ''),
(9563, 0, 'itIT', 'Mio signore, devo raggiungere la sommità del tempio.', ''),
(9564, 0, 'itIT', 'Vuoi dire l''iceberg?', ''),
(9565, 0, 'itIT', 'E tutta questa attrezzatura serve solo per esaminare del ghiaccio?', ''),
(9566, 0, 'itIT', 'È solo del ghiaccio. Perché tanto interesse?', ''),
(9567, 0, 'itIT', 'Testate a Razzo? Non è un approccio un po''... aggressivo?', ''),
