(9573, 2, 'itIT', 'Voglio scambiare l''Essenza d''Ambra con l''Essenza di Smeraldo.', ''),
(9573, 3, 'itIT', 'Voglio scambiare l''Essenza di Rubino con l''Essenza di Smeraldo.', ''),
