(9575, 3, 'itIT', 'Quali abilità hanno i Drachi di Rubino?', ''),
(9575, 4, 'itIT', 'Qual è l''abilità suprema dei Drachi di Rubino?', ''),
(9576, 0, 'itIT', 'Vorrei servirmi della scuderia.', ''),
(9578, 0, 'itIT', 'Insegnami, ti prego.', ''),
(9580, 0, 'itIT', 'Mi interessa addestrarmi nelle arti dei Maghi.', ''),
(9580, 1, 'itIT', 'Vorrei riassegnare i miei talenti.', ''),
(9581, 0, 'itIT', 'Insegnami, ti prego.', ''),
(9584, 0, 'itIT', 'Mostrami dove posso volare.', ''),
(9586, 0, 'itIT', 'Perché mi trovo in questo luogo e in questo momento?', ''),
(9586, 2, 'itIT', 'Cromie, sappiamo entrambi cosa sta per accadere in questo flusso temporale. L''abbiamo già visto. Non puoi portarci direttamente al punto in cui dovremo entrare in azione?', ''),
(9590, 0, 'itIT', 'E perché mai dovrei voler usare un Segatronchi?', ''),
(9592, 0, 'itIT', 'Dove posso recuperare una Chiave del Segatronchi Riparato?', ''),
(9594, 0, 'itIT', 'Di quale decisione si tratta?', ''),
(9595, 0, 'itIT', 'Lo Stormo dei Draghi dell''Infinito come ha intenzione di interferire?', ''),
(9603, 0, 'itIT', 'Esca dei Dragoni, eh? Va'' a prendere Tempesta Glaciale!', ''),
(9607, 0, 'itIT', 'E va bene, prenderò la tua mistura.', ''),
(9610, 0, 'itIT', 'Secondo te che hanno in mente?', ''),
(9611, 0, 'itIT', 'Vuoi che faccia COSA?', ''),
(9612, 0, 'itIT', 'Va bene, Cromie.', ''),
(9614, 1, 'itIT', 'Fammi vedere la tua merce.', ''),
(9615, 0, 'itIT', 'Dai la mano a Drakuru.', ''),
(9615, 1, 'itIT', 'Drakuru, mi serve un altro dei tuoi elisir.', ''),
(9618, 0, 'itIT', 'Emilune, mi manda l''Ammiraglio Keller. Ti prego, inviami al Forte di Guardia dell''Ovest!', ''),
(9619, 0, 'itIT', 'Come funziona tutto questo?', ''),
(9619, 1, 'itIT', 'Mostrami cos''hai da vendere.', ''),
(9626, 0, 'itIT', 'Teletrasportami alla Scogliera d''Ambra, per favore.', ''),
(9628, 2, 'itIT', 'Fammi vedere la tua merce.', ''),
(9629, 0, 'itIT', 'Sentiero di Illidan', ''),
(9629, 1, 'itIT', 'Sfera da Ballo', ''),
(9629, 2, 'itIT', 'Evocatore Etereo', ''),
(9629, 3, 'itIT', 'Che altre promozioni hai?', ''),
(9632, 0, 'itIT', 'Fammi vedere la tua merce.', ''),
(9640, 0, 'itIT', 'Soldato, hai nuovi ordini: devi tornare dal Sergente per fare rapporto!', ''),
(9647, 0, 'itIT', 'A te... Capitano del Terrore! Rendimi pirata per un giorno.', ''),
(9648, 0, 'itIT', 'Ti serve una mano ad assaggiare?', ''),
(9648, 1, 'itIT', 'Assaggiamone ancora!', ''),
(9648, 2, 'itIT', 'Ancora uno!', ''),
(9650, 0, 'itIT', 'Vai là fuori e fai pentire quelle creature del Flagello di essere rinate!', ''),
(9652, 0, 'itIT', 'Salute!', ''),
(9653, 0, 'itIT', 'Sì, mio Principe. Siamo pronti.', ''),
(9666, 0, 'itIT', 'Ma io ho guidato la mia trivella fin quaggiù...', ''),
(9667, 0, 'itIT', 'Ci sono.', ''),
(9668, 0, 'itIT', 'Sono pronto per cominciare. Qual è il primo ingrediente che ti serve?', ''),
(9669, 37476, 'itIT', 'Brann, l''onore sarebbe tutto nostro!', ''),
(9670, 36142, 'itIT', 'Muoviamoci, Brann! Basta con le lezioni di storia!', ''),
(9674, 0, 'itIT', 'Direi che mi posso fidare di te... Muoviamoci.', ''),
(9676, 0, 'itIT', 'Sire, sono pronto a combattere contro il Signore del Terrore.', ''),
(9677, 0, 'itIT', '<Chinati e aiuta l''Oracolo Cantapioggia Ferito a rialzarsi.>', ''),
(9678, 0, 'itIT', 'Sciamano Vekjik, ho parlato con le lingue grandi e desiderano la pace. Ho portato questa offerta da parte loro.', ''),
(9680, 0, 'itIT', 'Vostra Altezza, facciamo solo ciò che è meglio per Lordaeron.', ''),
(9681, 0, 'itIT', 'Principe Arthas, facci strada.', ''),
(9682, 0, 'itIT', 'B.O.M.B.A. da Festa', ''),
(9682, 1, 'itIT', 'Bandiera della Provocazione', ''),
(9682, 2, 'itIT', 'Orso Cavalcabile', ''),
(9682, 3, 'itIT', 'Che altre promozioni hai?', ''),
(9683, 0, 'itIT', 'Credi di potermi dare un passaggio su una di quelle macchine volanti?', ''),
(9684, 0, 'itIT', 'Ora possiamo andare al tuo villaggio.', ''),
(9686, 0, 'itIT', 'No no... Non avevo intenzione di tradire il tuo popolo. Mi stavo solo difendendo. È stato un malinteso.', ''),
(9687, 0, 'itIT', 'Grande e potente Har''koa, ti prego di chiamare uno dei tuoi figli affinché possa condurmi di nascosto all''Altare di Quetz''lun.', ''),
(9691, 0, 'itIT', 'Dama Alistra, ho bisogno d''addestramento.', ''),
(9691, 1, 'itIT', 'Vorrei riassegnare i miei talenti.', ''),
(9692, 0, 'itIT', 'Ser Thorval, ho bisogno d''addestramento.', ''),
(9692, 1, 'itIT', 'Vorrei riassegnare i miei talenti.', ''),
(9693, 0, 'itIT', 'Amal''thazad, ho bisogno d''addestramento.', ''),
(9693, 1, 'itIT', 'Vorrei riassegnare i miei talenti.', ''),
(9695, 0, 'itIT', 'Sono pronto.', ''),
(9696, 0, 'itIT', 'Per Lordaeron!', ''),
(9708, 0, 'itIT', 'E adesso che facciamo?', ''),
(9709, 0, 'itIT', 'Ho perso Nass...', ''),
(9709, 1, 'itIT', 'Ho perso il mio Girocollo Stregato.', ''),
(9713, 0, 'itIT', 'Possiamo cominciare con la distillazione quando vuoi, ehm, Brillo.', ''),
(9714, 0, 'itIT', 'Stefan mi ha detto che tu sei in grado di mostrarmi a cosa serve questo oggetto.', ''),
(9717, 0, 'itIT', 'Cosa nascondi sotto quel pezzo di carne?', ''),
(9720, 0, 'itIT', 'Voglio fermare il Flagello quanto te. Come posso esserti d''aiuto?', ''),
(9721, 0, 'itIT', 'Puoi fidarti di me. Il Re dei Lich non è mio alleato.', ''),
(9722, 0, 'itIT', 'Non fallirò.', ''),
(9724, 0, 'itIT', 'Potresti darmi un''arancia?', ''),
(9724, 1, 'itIT', 'Hai delle banane in più?', ''),
(9724, 2, 'itIT', 'Mi farebbe proprio comodo una papaya.', ''),
(9728, 0, 'itIT', '<Controlla il battito...>', ''),
(9731, 0, 'itIT', 'Drakuru, sono pronto ad accompagnarti.', ''),
(9731, 1, 'itIT', 'Gorbag mi ha mostrato l''Impero dei Drakkari. Non vedo l''ora di aiutarti a conquistarlo!', ''),
(9731, 2, 'itIT', 'Ho rimesso in riga i Geist Ammorbati!', ''),
(9731, 3, 'itIT', 'Ho sconfitto Darmuk! Cos''altro posso fare per servirti?', ''),
(9731, 4, 'itIT', 'I Capi Tribù Drakkari sono stati catturati! Cos''altro vuoi che faccia?', ''),
(9731, 5, 'itIT', 'Drakuru, ho assistito alla tua imponente operazione. Quando metteremo in atto il tuo piano?', ''),
(9732, 0, 'itIT', 'Ah, puoi farmi fare il giro di Zul''drak?', ''),
(9733, 2, 'itIT', 'Fammi vedere la tua merce.', ''),
(9735, 0, 'itIT', 'Sì, Hargus. Voglio acquistare dei rifornimenti.', ''),
