(21167, 1, 'itIT', 'Come combattono i Cavalieri della Crociata d''Argento?', ''),
(21188, 1, 'itIT', 'Come combattono i Cavalieri della Crociata d''Argento?', ''),
(21194, 0, 'itIT', 'Vorrei mettere il mio famiglio qui.', ''),
(21195, 1, 'itIT', 'Voglio dare un''occhiata alla tua merce.', ''),
(21208, 0, 'itIT', 'Gira la chiave per mettere in funzione la macchina.', ''),
(21210, 1, 'itIT', 'Tharnariun, ho perso la trappola. Potresti darmene un''altra?', ''),
(21211, 0, 'itIT', 'Dov''è l''assistente di Tirth?', ''),
(21212, 0, 'itIT', 'Dov''è l''assistente di Tirth?', ''),
(21213, 0, 'itIT', 'Ti prego di aprire la porta del cortile.', ''),
(21214, 0, 'itIT', 'Ti prego di aprire la porta del cortile.', ''),
(21215, 0, 'itIT', 'Dolcetto o scherzetto!', ''),
(21215, 2, 'itIT', 'Voglio dare un''occhiata alla tua merce.', ''),
(21217, 0, 'itIT', 'Dov''è l''assistente di Tirth?', ''),
(21221, 0, 'itIT', 'Vorrei addestrarmi.', ''),
(21221, 1, 'itIT', 'Vorrei riassegnare i miei talenti.', ''),
(21222, 0, 'itIT', 'Addestrami.', ''),
(21228, 0, 'itIT', 'Insegnami, ti prego.', ''),
(21248, 0, 'itIT', 'Esamina il cadavere in cerca del kit d''emergenza del pilota.', ''),
(21251, 1, 'itIT', 'Sì, sono pronto a partire per la Baia della S.P.R. & Co.', ''),
(21253, 0, 'itIT', 'Soldato Weeks, mi serve un altro travestimento.', ''),
(21255, 0, 'itIT', 'Ho un libro che potrebbe interessarti. Vuoi dargli un''occhiata?', ''),
(21257, 0, 'itIT', 'Consultiamo i presagi.', ''),
(21258, 0, 'itIT', 'Mi sembra di aver sentito parlare di questa magia.', ''),
(21259, 0, 'itIT', 'Arcanum? Questo nome mi è familiare...', ''),
(21260, 0, 'itIT', 'Quali oggetti?', ''),
(21262, 0, 'itIT', 'Falthir, mi serve aiuto per recuperare un pezzo del mio Completo degli Scriteriati.', ''),
(21272, 0, 'itIT', 'È bello vedere che le Lame Ardenti stiano riuscendo là dove il Concilio dell''Ombra ha fallito.', ''),
(21273, 0, 'itIT', 'Quindi i Lamarovente sono sacrificabili?', ''),
(21274, 0, 'itIT', 'Se c''è qualcosa che posso fare...', ''),
(21276, 0, 'itIT', 'Come facevi a saperlo? Voglio dire, sì, sto cercando quel frammento. Ce l''hai tu?', ''),
(21277, 0, 'itIT', 'D''accordo... dove l''hai nascosto?', ''),
(21279, 0, 'itIT', 'Ai pesci? Hai consegnato un oggetto che potrebbe salvare ogni forma di vita a Kalimdor a dei pesci?', ''),
(21281, 0, 'itIT', '...', ''),
(21282, 0, 'itIT', 'Hai dato il frammento in pasto a una tinca e l''hai collocata da qualche parte nelle acque del mare tra qui e i Regni Orientali? E questa tinca ha dei poteri speciali?', ''),
(21283, 0, 'itIT', 'Tu sei fuori di testa.', ''),
(21284, 0, 'itIT', 'Sono tutt''orecchi.', ''),
(21285, 0, 'itIT', 'Cosa?', ''),
(21287, 0, 'itIT', 'BENE! Se posso chiedere, come dovrei fare a procurarmi una Boa d''Arcanite?', ''),
(21288, 0, 'itIT', 'Ma...', ''),
(21289, 0, 'itIT', 'Io ho fiducia in te.', ''),
(21290, 0, 'itIT', 'Voglio risposte, Ogre!', ''),
(21292, 2, 'itIT', 'E tu pensi di poter mangiare tutto quello che vuoi? È chiaro che stai cercando di mangiare i Corrotti di Telaar.', ''),
(21293, 3, 'itIT', 'Questo porterà la guerra, Lump! Ci sarà guerra!', ''),
(21295, 0, 'itIT', 'Ho ucciso molti dei tuoi Ogre, Lantresor. Non ho paura.', ''),
(21310, 0, 'itIT', 'Mi serve un attimo del tuo tempo.', ''),
(21311, 0, 'itIT', 'Ah... sì, certo. Signor Guardiaforgia, c''è una cosa, all''interno di questo edificio, che desidero mostrarti.', ''),
(21312, 0, 'itIT', 'Salve, Eitrigg. Porto delle notizie dai Bastioni di Roccianera.', ''),
(21313, 0, 'itIT', 'C''è solo un Capoguerra, Eitrigg!', ''),
(21314, 0, 'itIT', 'In che senso?', ''),
(21315, 0, 'itIT', 'Valsalda??? Ma...', ''),
(21316, 0, 'itIT', 'Mi ricorderò sicuramente della tua offerta, Eitrigg.', ''),
(21317, 0, 'itIT', 'Ah, allora è così che sono riusciti a spingere i Ferroscuro nelle profondità di Roccianera.', ''),
(21318, 0, 'itIT', 'Forse c''è un modo?', ''),
(21319, 0, 'itIT', 'Come desideri, Eitrigg.', ''),
(21321, 0, 'itIT', 'Cos''è lo Juju?', ''),
(21322, 0, 'itIT', 'Le mie scuse, Non pensavo capissi ciò che stavo dicendo. Cosa ci fai qui?', ''),
(21323, 0, 'itIT', 'Davvero? Forse dovresti dirmi cos''è che ti rende tanto pensieroso.', ''),
(21324, 0, 'itIT', 'Che tipo di accordo?', ''),
(21325, 0, 'itIT', 'Come ha fatto a non rispettare l''accordo?', ''),
(21330, 0, 'itIT', 'Io non ho commesso alcun errore.', ''),
(21331, 0, 'itIT', 'Tu hai perso il senno, Nefarius. Parli per indovinelli.', ''),
(21332, 0, 'itIT', 'Fallo, ti prego.', ''),
(21400, 0, 'itIT', 'Mi serve un Rilevatore Cenariano.', ''),
(21400, 1, 'itIT', 'Quali piante di Vilbosco potrebbero essere corrotte?', ''),
(21402, 0, 'itIT', 'Ho deciso! Voglio dimenticare la mia esperienza nell''Alchimia!', 'Dimenticare una conoscenza è un''impresa costosa. Sei $gdisposto:disposta; a pagare?'),
(21403, 0, 'itIT', 'Ho deciso! Voglio dimenticare la mia esperienza nell''Alchimia!', 'Dimenticare una conoscenza è un''impresa costosa. Sei $gdisposto:disposta; a pagare?'),
(21404, 0, 'itIT', 'Ho deciso! Voglio dimenticare la mia esperienza nell''Alchimia!', 'Dimenticare una conoscenza è un''impresa costosa. Sei $gdisposto:disposta; a pagare?'),
(21893, 0, 'itIT', 'Consegnami la Pietraluna di Furialunga e ti lascerò andare.', ''),
(30201, 0, 'itIT', 'Salve, o antico. Ho fatto tutto ciò che mi era stato chiesto. Ora sono io a chiederti Rhok''delar.', ''),
(30201, 1, 'itIT', 'Salve, o antico. Ho fatto tutto ciò che mi era stato chiesto. Ora sono io a chiederti Lok''delar.', ''),
(51000, 0, 'itIT', 'Ho qualcos''altro da chiederti.', ''),
(51001, 0, 'itIT', 'Ho qualcos''altro da chiederti.', ''),
(51002, 0, 'itIT', 'Ho qualcos''altro da chiederti.', ''),
(51003, 0, 'itIT', 'Ho qualcos''altro da chiederti.', ''),
(54000, 0, 'itIT', 'Alza la coda del Leopardo del Gelo per vedere se è maschio o femmina.', ''),
(55000, 0, 'itIT', 'Alza la coda dell''Orso Zampafredda per vedere se è maschio o femmina.', ''),
(56000, 0, 'itIT', 'Signori del Terrore? Forse intendi Sire Sacramorte. Ti manda i suoi saluti e ha un messaggio per te...', ''),
(56001, 0, 'itIT', 'No, Ulathek. Conosce il tuo segreto. Sa del complotto che stai ordendo con Sire Hel''nurath di Xoroth.', ''),
(56002, 0, 'itIT', 'Non è una menzogna, traditore. Sacramorte vuole il tuo cuore e io glielo darò.', ''),
(57000, 0, 'itIT', 'Qual è il tuo ruolo?', ''),
(57001, 0, 'itIT', 'Cosa sono le Placche di Uldum?', ''),
(57002, 0, 'itIT', 'Dove sono le Placche di Uldum?', ''),
(57003, 0, 'itIT', 'Scusa? Siamo stati "riscadenzati per una visita"? Cosa significa?!?', ''),
(57004, 0, 'itIT', 'Allora... cosa c''è dentro a Uldum?', ''),
(57005, 0, 'itIT', 'Tornerò quando avrò le Placche di Uldum.', ''),
(57006, 0, 'itIT', 'Ho perso l''Amuleto di Sire Valthalak!', ''),
(57006, 1, 'itIT', 'Ho perso un pezzo dell''Amuleto di Sire Valthalak!', ''),
(57006, 2, 'itIT', 'Ho perso il Braciere del Richiamo!', ''),
(57006, 3, 'itIT', 'Bodley, dimmi che cosa sta succedendo.', ''),
(57007, 0, 'itIT', 'Mi stavi raccontando della Lama Velata e di come tu abbia accettato la missione sbagliata.', ''),
(57008, 0, 'itIT', 'No, no, ti prego, continua... deve essere colpa del fumo che c''è quassù.', ''),
(57009, 0, 'itIT', 'Vai avanti, Bodley, ti prego.', ''),
(57010, 0, 'itIT', 'Pensavo che avessi quasi finito.', ''),
(57011, 0, 'itIT', 'Cos''è successo alla Lama Velata, la tua compagnia di mercenari?', ''),
(57015, 0, 'itIT', 'Sì, ho controllato, e non trovo più il frammento superiore!', ''),
(57015, 1, 'itIT', 'Sì, ho controllato e non trovo più il frammento sinistro!', ''),
(57018, 0, 'itIT', 'Sì, ti prego, evocalo di nuovo!', ''),
(57023, 0, 'itIT', 'Nat, voglio comprare le tue Esche Fanguzzole!', ''),
(57023, 1, 'itIT', 'Come faccio a catturare le Fanguzzole per la tua esca?', ''),
(61025, 0, 'itIT', 'Addestrami.', '');
